// Package license loads and validates Wachd license keys and enforces tier limits.
//
// Three tiers exist:
//
//	opensource  — no key required; hardcoded limits (1 team, 5 users, 1 000 alerts/month)
//	smb         — signed JWT key; limits embedded in token payload
//	enterprise  — signed JWT key; limits embedded in token payload
//
// The token is a compact JWT (header.payload.signature) signed with Ed25519.
// The private key lives in the private wachd-licensing repository and is never
// committed here. Only the public key is embedded in the binary.
package license

import (
	"crypto/ed25519"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"time"
)

// Tier identifies the license tier.
type Tier string

const (
	TierOpenSource Tier = "opensource"
	TierSMB        Tier = "smb"
	TierEnterprise Tier = "enterprise"
)

// OSS hardcoded limits — cannot be raised without a valid paid license key.
// These are constants so the compiler can inline them; a fork that removes the
// limit checks is a license violation, not a technical bypass.
const (
	OSSMaxTeams       = 1
	OSSMaxUsers       = 5
	OSSMaxAlertsMonth = 1_000
)

// gracePeriod is how long an expired key continues to work before the binary
// drops back to OSS limits. Gives customers time to renew without an outage.
const gracePeriod = 7 * 24 * time.Hour

// publicKeys maps key IDs (kid) to their hex-encoded Ed25519 public keys.
// To rotate: generate a new keypair in wachd.ee, add it here as "v2", keep
// "v1" until all v1-signed licenses have expired, then remove "v1".
//
// Corresponding private keys: stored in wachd.ee (private repo).
var publicKeys = map[string]string{
	"v1": "472c48133edeaae3b87b321a096dbaa3e0bd5713833c40331bc559f2d3594a6f",
}

// License holds the decoded, verified limits for this deployment.
// All callers should use the accessor methods rather than reading fields directly.
type License struct {
	Tier           Tier
	MaxTeams       int
	MaxUsers       int
	MaxAlertsMonth int
	CustomerName   string
	JTI            string // unique license ID — used for revocation checks
	ExpiresAt      time.Time
	IsGracePeriod  bool
}

// OSS returns the open-source tier license with hardcoded limits.
// This is always returned when no key is configured or when a key is invalid.
func OSS() *License {
	return &License{
		Tier:           TierOpenSource,
		MaxTeams:       OSSMaxTeams,
		MaxUsers:       OSSMaxUsers,
		MaxAlertsMonth: OSSMaxAlertsMonth,
	}
}

// Load parses and verifies a license key string using the embedded public keys.
//
//   - Empty string  → returns OSS(), nil (no key configured is valid)
//   - Unknown kid   → returns OSS(), non-nil error
//   - Invalid key   → returns OSS(), non-nil error (caller should log a warning)
//   - Expired key within grace period → returns paid license, IsGracePeriod=true
//   - Expired key beyond grace period → returns OSS(), non-nil error
func Load(keyStr string) (*License, error) {
	return loadWithKeys(keyStr, publicKeys)
}

// LoadWithKey is like Load but uses a single public key hex instead of the
// embedded production keys. Only intended for use in tests.
func LoadWithKey(keyStr, publicKeyHex string) (*License, error) {
	return loadWithKeys(keyStr, map[string]string{"v1": publicKeyHex})
}

func loadWithKeys(keyStr string, keys map[string]string) (*License, error) {
	if strings.TrimSpace(keyStr) == "" {
		return OSS(), nil
	}

	c, err := verifyAndDecode(keyStr, keys)
	if err != nil {
		return OSS(), err
	}

	exp := time.Unix(c.ExpiresAt, 0)
	now := time.Now()
	grace := false

	if now.After(exp) {
		if now.After(exp.Add(gracePeriod)) {
			return OSS(), fmt.Errorf("license expired on %s (grace period ended — renew at wachd.io)",
				exp.Format("2006-01-02"))
		}
		grace = true
	}

	tier := Tier(c.Tier)
	if tier != TierSMB && tier != TierEnterprise {
		return OSS(), fmt.Errorf("unknown license tier %q", c.Tier)
	}
	if c.MaxTeams <= 0 || c.MaxUsers <= 0 || c.MaxAlerts <= 0 {
		return OSS(), errors.New("license payload contains zero or negative limits")
	}
	if c.JTI == "" {
		return OSS(), errors.New("license payload missing jti claim")
	}

	return &License{
		Tier:           tier,
		MaxTeams:       c.MaxTeams,
		MaxUsers:       c.MaxUsers,
		MaxAlertsMonth: c.MaxAlerts,
		CustomerName:   c.CustomerName,
		JTI:            c.JTI,
		ExpiresAt:      exp,
		IsGracePeriod:  grace,
	}, nil
}

// IsPaid returns true for SMB and Enterprise tiers.
func (l *License) IsPaid() bool {
	return l.Tier == TierSMB || l.Tier == TierEnterprise
}

// IsEnterprise returns true only for the Enterprise tier.
func (l *License) IsEnterprise() bool {
	return l.Tier == TierEnterprise
}

// ── JWT verification ──────────────────────────────────────────────────────────

// jwtClaims is the expected payload of a Wachd license JWT.
type jwtClaims struct {
	Issuer       string `json:"iss"`
	Subject      string `json:"sub"` // customer ID
	JTI          string `json:"jti"` // unique license ID — revocation handle
	ExpiresAt    int64  `json:"exp"`
	Tier         string `json:"tier"`
	MaxTeams     int    `json:"max_teams"`
	MaxUsers     int    `json:"max_users"`
	MaxAlerts    int    `json:"max_alerts_month"`
	CustomerName string `json:"customer_name"`
}

// jwtHeader is used only to extract the kid field for key lookup.
type jwtHeader struct {
	KID string `json:"kid"`
}

// verifyAndDecode verifies the Ed25519 signature and decodes the JWT payload.
// It selects the public key by reading the kid field from the JWT header.
// It does NOT check expiry — that is the caller's responsibility.
func verifyAndDecode(token string, keys map[string]string) (*jwtClaims, error) {
	parts := strings.Split(token, ".")
	if len(parts) != 3 {
		return nil, errors.New("malformed license key: expected header.payload.signature")
	}

	rawHeader, err := base64.RawURLEncoding.DecodeString(parts[0])
	if err != nil {
		return nil, fmt.Errorf("decode license header: %w", err)
	}
	var hdr jwtHeader
	if err := json.Unmarshal(rawHeader, &hdr); err != nil {
		return nil, fmt.Errorf("parse license header: %w", err)
	}
	if hdr.KID == "" {
		return nil, errors.New("license header missing kid field")
	}

	pubKeyHex, ok := keys[hdr.KID]
	if !ok {
		return nil, fmt.Errorf("unknown key id %q — binary may need upgrading", hdr.KID)
	}

	pubKeyBytes, err := hex.DecodeString(pubKeyHex)
	if err != nil || len(pubKeyBytes) != ed25519.PublicKeySize {
		return nil, errors.New("binary has an invalid embedded public key — please report this")
	}

	sig, err := base64.RawURLEncoding.DecodeString(parts[2])
	if err != nil {
		return nil, fmt.Errorf("decode license signature: %w", err)
	}

	// Signature covers header.payload exactly as they appear in the token.
	msg := parts[0] + "." + parts[1]
	if !ed25519.Verify(pubKeyBytes, []byte(msg), sig) {
		return nil, errors.New("license signature verification failed — key may be tampered or forged")
	}

	payload, err := base64.RawURLEncoding.DecodeString(parts[1])
	if err != nil {
		return nil, fmt.Errorf("decode license payload: %w", err)
	}

	var c jwtClaims
	if err := json.Unmarshal(payload, &c); err != nil {
		return nil, fmt.Errorf("decode license claims: %w", err)
	}
	if c.Issuer != "wachd-license" {
		return nil, fmt.Errorf("invalid license issuer %q", c.Issuer)
	}

	return &c, nil
}

package license

import (
	"github.com/gofiber/fiber/v2"

	licenserpc "github.com/werbot/werbot/internal/core/license/proto/rpc"
	licensemessage "github.com/werbot/werbot/internal/core/license/proto/message"
	"github.com/werbot/werbot/internal/web/session"
	"github.com/werbot/werbot/pkg/utils/protoutils"
	"github.com/werbot/werbot/pkg/utils/webutil"
)

// @Summary Get License Information
// @Description Retrieve the license information for the authenticated profile
// @Tags license
// @Produce json
// @Success 200 {object} webutil.HTTPResponse{result=licensemessage.License_Response}
// @Failure 400,401,404,500 {object} webutil.HTTPResponse{result=string}
// @Router /v1/license/info  [get]
func (h *Handler) licenseInfo(c *fiber.Ctx) error {
	sessionData := session.AuthProfile(c)
	if !sessionData.IsProfileAdmin() {
		return webutil.StatusNotFound(c, nil)
	}

	rClient := licenserpc.NewLicenseHandlersClient(h.Grpc)
	lic, err := rClient.License(c.UserContext(), &licensemessage.License_Request{})
	if err != nil {
		return webutil.FromGRPC(c, err)
	}

	result, err := protoutils.ConvertProtoMessageToMap(lic)
	if err != nil {
		return webutil.FromGRPC(c, err)
	}

	return webutil.StatusOK(c, "License", result)
}

package license

import (
	"context"
	"encoding/json"
	"os"
	"time"

	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"
	"google.golang.org/protobuf/types/known/timestamppb"

	"github.com/werbot/werbot/internal"
	licensemessage "github.com/werbot/werbot/internal/core/license/proto/message"
	"github.com/werbot/werbot/internal/trace"
	license_lib "github.com/werbot/werbot/pkg/license"
	"github.com/werbot/werbot/pkg/uuid"
)

// License is ...
func (h *Handler) License(_ context.Context, in *licensemessage.License_Request) (*licensemessage.License_Response, error) {
	licenseFilePath := internal.GetString("LICENSE_FILE", "/license.key")
	licensePublicKey := internal.GetString("LICENSE_KEY_PUBLIC", "")

	licByte := in.GetLicense()
	if licByte == nil {
		var err error
		licByte, err = os.ReadFile(licenseFilePath)
		if err != nil || licensePublicKey == "" {
			return osLicense(), nil
		}
	}

	return eeLicense(licByte, licensePublicKey)
}

func osLicense() *licensemessage.License_Response {
	now := time.Now().UTC()

	return &licensemessage.License_Response{
		Issued:     "free",
		Customer:   "Mr. Robot",
		Subscriber: uuid.New(),
		Type:       "open source",
		IssuedAt:   timestamppb.New(now),
		ExpiresAt:  timestamppb.New(now.AddDate(1, 0, 0)),
		Expired:    true,
		Modules:    []string{"module1", "module2", "module3"},
		Limits: map[string]int32{
			"Companies": 99,
			"Schemes":   99,
			"Users":     99,
		},
	}
}

func eeLicense(licByte []byte, publicKey string) (*licensemessage.License_Response, error) {
	lic, err := license_lib.DecodePublicKey([]byte(publicKey))
	if err != nil {
		errGRPC := status.Error(codes.NotFound, trace.MsgLicenseKeyIsBroken)
		return nil, trace.Error(errGRPC, log, nil)
	}

	licDecode, err := lic.Decode(licByte)
	if err != nil {
		errGRPC := status.Error(codes.PermissionDenied, trace.MsgLicenseStructureIsBroken)
		return nil, trace.Error(errGRPC, log, nil)
	}

	response := &licensemessage.License_Response{
		Issued:     licDecode.License.Iss,
		Customer:   licDecode.License.Cus,
		Subscriber: licDecode.License.Sub,
		Type:       licDecode.License.Typ,
		IssuedAt:   timestamppb.New(licDecode.License.Iat),
		ExpiresAt:  timestamppb.New(licDecode.License.Exp),
		Expired:    lic.Expired(),
	}

	licData := map[string]any{}
	if err := json.Unmarshal(licDecode.License.Dat, &licData); err != nil {
		return nil, trace.Error(err, log, trace.MsgStructureIsBroken)
	}

	response.Limits = map[string]int32{
		"Companies": int32(licData["companies"].(float64)),
		"Schemes":   int32(licData["schemes"].(float64)),
		"Users":     int32(licData["users"].(float64)),
	}

	for _, item := range licData["modules"].([]interface{}) {
		response.Modules = append(response.Modules, item.(string))
	}

	return response, nil
}

package license

import (
	"bytes"
	"encoding/base64"
	"encoding/json"
	"encoding/pem"
	"errors"
	"time"

	"golang.org/x/crypto/ed25519"
)

var (
	// ErrLicenseKeyIsBroken indicates that the license key is broken.
	ErrLicenseKeyIsBroken = errors.New("the license key is broken")

	// ErrLicenseStructureIsBroken indicates that the license structure is broken.
	ErrLicenseStructureIsBroken = errors.New("the license has a broken structure")

	// ErrFailedToOpenLicenseFile indicates that opening the license file failed.
	ErrFailedToOpenLicenseFile = errors.New("failed to open license file")
)

// Private is ...
type Private struct {
	key     ed25519.PrivateKey
	License License
}

// Public is ...
type Public struct {
	key     ed25519.PublicKey
	License License
}

// License file structure
type License struct {
	Iss string          `json:"iss,omitempty"` // Issued By
	Cus string          `json:"cus,omitempty"` // Customer ID
	Sub string          `json:"sub,omitempty"` // Subscriber ID
	Typ string          `json:"typ,omitempty"` // License Type
	Ips string          `json:"ips,omitempty"` // Ip's
	Iat time.Time       `json:"iat,omitempty"` // Issued At
	Exp time.Time       `json:"exp,omitempty"` // Expires At
	Dat json.RawMessage `json:"dat,omitempty"` // Data
}

// DecodePrivateKey is decode private key from base64
func DecodePrivateKey(privateKey []byte) (*Private, error) {
	decodedPrivateKey, err := decodeKey(privateKey)
	if err != nil {
		return nil, err
	}

	return &Private{
		key: ed25519.PrivateKey(decodedPrivateKey),
	}, nil
}

// Encode is a generate new license
func (l *Private) Encode() ([]byte, error) {
	if l.key == nil {
		return nil, errors.New("private key is not set")
	}

	msg, err := json.Marshal(l.License)
	if err != nil {
		return nil, err
	}

	sig := ed25519.Sign(l.key, msg)
	buf := &bytes.Buffer{}
	buf.Write(sig)
	buf.Write(msg)

	block := &pem.Block{
		Type:  "LICENSE KEY",
		Bytes: buf.Bytes(),
	}
	return pem.EncodeToMemory(block), nil
}

// DecodePublicKey and decode public key from base64
func DecodePublicKey(publicKey []byte) (*Public, error) {
	decodedPublicKey, err := decodeKey(publicKey)
	if err != nil {
		return nil, err
	}

	return &Public{
		key: ed25519.PublicKey(decodedPublicKey),
	}, nil
}

// Decode license file
func (l *Public) Decode(data []byte) (*Public, error) {
	if l.key == nil {
		return nil, errors.New("public key is not set")
	}

	block, _ := pem.Decode(data)
	if block == nil || len(block.Bytes) < ed25519.SignatureSize {
		return nil, errors.New("Malformed License")
	}

	sig := block.Bytes[:ed25519.SignatureSize]
	msg := block.Bytes[ed25519.SignatureSize:]

	verified := ed25519.Verify(l.key, msg, sig)
	if !verified {
		return nil, errors.New("invalid license")
	}
	out := &License{}
	err := json.Unmarshal(msg, out)
	l.License = *out
	return l, err
}

// Expired is a ...
func (l *Public) Expired() bool {
	return !l.License.Exp.IsZero() && time.Now().After(l.License.Exp)
}

// Info is ...
func (l *Public) Info() License {
	return l.License
}

func decodeKey(b []byte) ([]byte, error) {
	enc := base64.StdEncoding
	buf := make([]byte, enc.DecodedLen(len(b)))
	n, err := enc.Decode(buf, b)
	if err != nil {
		return nil, errors.New("illegal base64 data")
	}
	return buf[:n], nil
}

from django.conf import settings
from api.models import ActivatedPhaseLicense
from graphql import GraphQLError
from api.utils.access.permissions import user_is_org_member


def resolve_license(root, info):
    return settings.PHASE_LICENSE


def resolve_organisation_license(root, info, organisation_id):
    if not user_is_org_member(info.context.user.userId, organisation_id):
        raise GraphQLError("You don't have access to this organisation")

    return (
        ActivatedPhaseLicense.objects.filter(organisation__id=organisation_id)
        .order_by("-activated_at")
        .first()
    )

